// GATE 1 PREVIEW — temporary (noindex). Loop theme for Carbon, built from data.
// Data: src/design-system/carbon/carbon-report.json (generated by `npm run tokens:carbon`).
import type { Metadata } from "next";
import report from "@/design-system/carbon/carbon-report.json";
import { ThemeShowcase } from "./ThemeShowcase";
import "../carbon-gate.scss";
import "./theme.scss";

export const metadata: Metadata = { title: "Tema Loop para Carbon", robots: { index: false, follow: false } };

type Tok = (typeof report.tokens)[number];
const group = (t: Tok) => (t.kind === "component" ? "button" : t.name.split("-")[0]);
const groups = report.tokens.reduce<Record<string, Tok[]>>((acc, t) => {
  (acc[group(t)] ??= []).push(t);
  return acc;
}, {});
const isColor = (v: string | undefined) => !!v && /^#|^rgb/.test(v);

function Swatch({ value, label }: { value?: string; label: string }) {
  if (!isColor(value)) return <code className="theme__code">{value}</code>;
  return (
    <span className="theme__swatch">
      {/* Dynamic, data-driven colour: inline style is the documented exception. */}
      <span className="theme__chip" style={{ background: value }} aria-hidden="true" />
      <code className="theme__code">{value}</code>
      <span className="sr-only">{label}</span>
    </span>
  );
}

export default function CarbonThemePage() {
  const { summary } = report;
  return (
    <div className="carbon-gate theme">
      <header className="theme__intro">
        <h1>Tema Loop para Carbon</h1>
        <p>
          {summary.tokens} tokens Carbon apontam para tokens Loop. {summary.checks} verificações WCAG AA ·{" "}
          <strong>{summary.failed === 0 ? "todas passam" : `${summary.failed} falham`}</strong>. O esquema
          claro/escuro segue o sistema operacional.
        </p>
      </header>

      <section aria-labelledby="t-live">
        <h2 id="t-live">Componentes</h2>
        <ThemeShowcase />
      </section>

      <section aria-labelledby="t-contrast">
        <h2 id="t-contrast">Contraste (WCAG 2.1 AA)</h2>
        <div className="theme__scroll" role="region" aria-label="Tabela de contraste" tabIndex={0}>
          <table className="theme__table">
            <thead>
              <tr>
                <th scope="col">Uso</th>
                <th scope="col">Par</th>
                <th scope="col">Mín.</th>
                <th scope="col">Claro</th>
                <th scope="col">Escuro</th>
              </tr>
            </thead>
            <tbody>
              {report.checks.map((c) => (
                <tr key={`${c.fg}-${c.bg}`}>
                  <th scope="row">{c.label}</th>
                  <td><code className="theme__code">{c.fg}</code> / <code className="theme__code">{c.bg}</code></td>
                  <td>{c.min}:1</td>
                  {(["light", "dark"] as const).map((s) => (
                    <td key={s} className={c[s].pass ? "theme__pass" : "theme__fail"}>
                      <span className="theme__pair" aria-hidden="true">
                        {/* Sample: real fg on real bg. Text pairs show "Aa"; non-text (3:1) pairs show a shape. */}
                        {c.min >= 4.5 ? (
                          <span className="theme__sample" style={{ color: c[s].fg, background: c[s].bg }}>Aa</span>
                        ) : (
                          <span className="theme__sample theme__sample--shape" style={{ color: c[s].fg, background: c[s].bg }} />
                        )}
                      </span>
                      {c[s].ratio.toFixed(2)}:1 {c[s].pass ? "✓" : "✗"}
                      <span className="sr-only">{c[s].pass ? "passa" : "falha"}</span>
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>

      <section aria-labelledby="t-tokens">
        <h2 id="t-tokens">Tokens</h2>
        <p>Regra Loop → valor resolvido. A coluna “Ao vivo” lê <code className="theme__code">var(--cds-*)</code> na página.</p>
        {Object.entries(groups).map(([g, toks]) => (
          <details key={g} className="theme__group">
            <summary>
              {g} <span className="theme__count">{toks.length}</span>
            </summary>
            <div className="theme__scroll" role="region" aria-label={`Tokens ${g}`} tabIndex={0}>
              <table className="theme__table">
                <thead>
                  <tr>
                    <th scope="col">Token</th>
                    <th scope="col">Regra</th>
                    <th scope="col">Ao vivo</th>
                    <th scope="col">Claro</th>
                    <th scope="col">Escuro</th>
                  </tr>
                </thead>
                <tbody>
                  {toks.map((t) => (
                    <tr key={t.name}>
                      <th scope="row"><code className="theme__code">--cds-{t.name}</code></th>
                      <td>
                        <code className="theme__code">{t.rule.light}</code>
                        {t.rule.dark !== t.rule.light && <><br /><code className="theme__code">dark: {t.rule.dark}</code></>}
                      </td>
                      <td>
                        {isColor(t.value.light) ? (
                          <span className="theme__chip" style={{ background: `var(--cds-${t.name})` }} aria-hidden="true" />
                        ) : (
                          <code className="theme__code">var(--cds-{t.name})</code>
                        )}
                      </td>
                      <td><Swatch value={t.value.light} label={`claro ${t.value.light}`} /></td>
                      <td><Swatch value={t.value.dark} label={`escuro ${t.value.dark}`} /></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </details>
        ))}
      </section>
    </div>
  );
}
